import java.util.function.BooleanSupplier;
import org.json.*;
/** G05-only bridge: actual local Store reads, paired frozen evidence, separate v2 history. */
final class HostCandidateBackground {
 static final String SCHEMA="native-candidate-background-host/v1";static final int APP=0x43424732,LIMIT=12*1024*1024;
 final File business,recent,leaders,evidence;
 interface Hooks {Instant now();void betweenReads()throws Exception;default void beforeCommit()throws Exception{}}
 interface Read {JSONObject get()throws Exception;}
 final Hooks hooks;
 HostCandidateBackground(File business,File recent,File leaders,File evidence){this(business,recent,leaders,evidence,null);}
 HostCandidateBackground(File business,File recent,File leaders,File evidence,Hooks hooks){this.business=business;this.recent=recent;this.leaders=leaders;this.evidence=evidence;this.hooks=hooks;}
 static void need(boolean ok,String why){LocalCandidateModel.require(ok,why);}
 static void active(BooleanSupplier c)throws Exception{SectorLeaderModel.active(c);}
 static String digest(Object o)throws Exception{return LocalCandidateBackgroundAdapter.sourceDigest(o);}
 void protectSources()throws Exception{for(File f:new File[]{business,recent,leaders})need(!f.getCanonicalFile().equals(evidence.getCanonicalFile()),"背景留存路径不得指向来源库");}
 static JSONObject observed(File path,Read read,BooleanSupplier c)throws Exception{active(c);boolean exists=path.isFile();JSONObject out=new JSONObject().put("exists",exists).put("readOk",false).put("data",new JSONObject());if(!exists)return out.put("reason","来源文件不存在");try{out.put("data",read.get());active(c);need(path.isFile(),"来源读取期间消失");out.put("readOk",true);}catch(Exception e){active(c);out.put("reason",e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()).put("data",new JSONObject());}return out;}
 JSONObject sources(List<String> accountIds,JSONObject quotes,BooleanSupplier c)throws Exception{
  JSONObject h=observed(business,()->{JSONObject raw=BusinessStore.readLedgerSnapshot(business,c);JSONArray ledgers=new JSONArray(),accounts=raw.getJSONArray("accounts");Set<String>found=new HashSet<>();for(int i=0;i<accounts.length();i++){JSONObject a=accounts.getJSONObject(i);String id=a.optString("id");if(!accountIds.contains(id))continue;need("ledger".equals(a.optString("type")),"明确账户已不在ledger范围");need(found.add(id),"账户身份重复");JSONObject portfolio=BusinessStore.portfolio(raw.getJSONArray("trades"),quotes,id);ledgers.put(new JSONObject().put("accountId",id).put("positions",portfolio.get("positions")).put("positionsComplete",true).put("basis","all-local-recorded-transactions").put("asOf",a.has("ledgerAsOf")?a.get("ledgerAsOf"):JSONObject.NULL));}need(found.size()==accountIds.size(),"明确账户已删除或不可用");return raw.put("ledgers",ledgers);},c);
  JSONObject r=observed(recent,()->new JSONObject().put("query","").put("sort","last_viewed").put("limit",10000).put("rows",new RecentStore(recent).list("","last_viewed",10000)),c);
  JSONObject l=observed(leaders,()->new SectorLeaderStore(leaders).read(c),c);return new JSONObject().put("holdings",h).put("recent",r).put("leaders",l);
 }
 JSONArray accounts(BooleanSupplier c)throws Exception{JSONArray rows=BusinessStore.readLedgerSnapshot(business,c).getJSONArray("accounts"),out=new JSONArray();Set<String>seen=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject a=rows.getJSONObject(i);if(!"ledger".equals(a.optString("type")))continue;String id=a.optString("id");need(!id.isEmpty()&&seen.add(id),"账户身份无效");out.put(new JSONObject().put("id",id).put("name",a.opt("name")));}return out;}
 JSONObject prepare(JSONArray source,String strategy,List<String> accountIds,JSONObject themeSelection,BooleanSupplier c)throws Exception{return prepare(source,strategy,accountIds,themeSelection,null,c);}
 JSONObject prepare(JSONArray source,String strategy,List<String> accountIds,JSONObject themeSelection,JSONObject businessSelection,BooleanSupplier c)throws Exception{
  active(c);need(accountIds!=null&&!accountIds.isEmpty()&&accountIds.size()<=100&&new HashSet<>(accountIds).size()==accountIds.size(),"请明确选择账本账户");JSONArray selected=new JSONArray(source.toString()),ids=new JSONArray();JSONObject quotes=new JSONObject();for(int i=0;i<selected.length();i++){JSONObject row=selected.getJSONObject(i);need(!row.has("backgroundInput"),"只能从未附加背景的当前候选输入开始");ids.put(row.get("id"));quotes.put(row.getString("id"),row.optJSONObject("quote"));}
  if(themeSelection!=null){JSONObject cat=themeCatalogue(c);CandidateThemeSelection.confirm(themeSelection,cat,c);if(businessSelection!=null)CandidateBusinessSelection.confirm(businessSelection,cat,themeSelection,c);need(LocalCandidateModel.canonical(themeSelection.getJSONArray("securities")).equals(LocalCandidateModel.canonical(selected)),"证券版本已变化，请重新预览");}
  JSONObject before=sources(accountIds,quotes,c);Instant cut=(hooks==null?Instant.now():hooks.now()).truncatedTo(ChronoUnit.MILLIS);if(hooks!=null)hooks.betweenReads();active(c);JSONObject after=sources(accountIds,quotes,c);need(digest(before).equals(digest(after)),"来源存在性、读取状态或正文在双读间变化，整批拒绝");if(themeSelection!=null){JSONObject cat=themeCatalogue(c);CandidateThemeSelection.confirm(themeSelection,cat,c);if(businessSelection!=null)CandidateBusinessSelection.confirm(businessSelection,cat,themeSelection,c);CandidateThemeSelection.clocks(themeSelection,cut);if(businessSelection!=null)CandidateBusinessSelection.clocks(businessSelection,cut);}String stamp=new java.time.format.DateTimeFormatterBuilder().appendInstant(3).toFormatter().format(cut);JSONObject wrapped=new JSONObject();
  for(String key:new String[]{"holdings","recent","leaders"}){JSONObject a=before.getJSONObject(key),b=after.getJSONObject(key),data=a.getJSONObject("data"),metadata=new JSONObject(a.toString());metadata.remove("data");boolean ok=a.getBoolean("exists")&&a.getBoolean("readOk");wrapped.put(key,new JSONObject().put("status",ok?"available":"unavailable").put("source","native-local/"+key).put("complete",ok).put("observedAt",stamp).put("beforeHash",digest(data)).put("afterHash",digest(b.get("data"))).put("data",data).put("readEvidence",metadata));}
  JSONObject raw=new JSONObject().put("schema","native-candidate-background-sources/v1").put("mode","current-observation").put("capturedAt",stamp).put("observedAt",stamp).put("selectedIds",ids).put("accountScope",new JSONObject().put("kind","explicit-ledger-accounts").put("accountIds",new JSONArray(accountIds))).put("sources",wrapped).put("hostPaths",new JSONObject().put("business",business.getAbsolutePath()).put("recent",recent.getAbsolutePath()).put("leaders",leaders.getAbsolutePath()));
  if(themeSelection!=null){raw.put("themeSelection",themeSelection);for(String key:new String[]{"themes","demand"}){JSONObject data=themeSelection.getJSONObject(key);wrapped.put(key,new JSONObject().put("status","available").put("source","native-local/explicit-selected-"+key).put("complete",true).put("observedAt",stamp).put("beforeHash",digest(data)).put("afterHash",digest(data)).put("data",data));}}
  if(businessSelection!=null){need(themeSelection!=null,"主营资料须绑定明确需求");raw.put("schema","native-candidate-background-sources/v2-business-demand").put("businessSelection",businessSelection);}
  JSONObject adapter=LocalCandidateBackgroundAdapter.freeze(raw),backgrounds=adapter.getJSONObject("backgrounds");for(int i=0;i<selected.length();i++){JSONObject row=selected.getJSONObject(i);row.put("backgroundInput",backgrounds.getJSONObject(row.getString("id")));}return new JSONObject().put("schema","native-candidate-background-preview/v1").put("adapter",adapter).put("inputs",selected).put("strategy",strategy);
 }
 JSONObject themeCatalogue(BooleanSupplier c)throws Exception{return BusinessStore.readCandidateThemeSnapshot(business,c);}
 void confirmLive(JSONObject raw,BooleanSupplier c)throws Exception{
  if(!raw.has("themeSelection"))return;JSONObject held=raw.getJSONObject("themeSelection");JSONObject cat=themeCatalogue(c);CandidateThemeSelection.confirm(held,cat,c);if("native-candidate-background-sources/v2-business-demand".equals(raw.optString("schema")))CandidateBusinessSelection.confirm(raw.getJSONObject("businessSelection"),cat,held,c);JSONObject quotes=new JSONObject();JSONArray ss=held.getJSONArray("securities");for(int i=0;i<ss.length();i++){JSONObject r=ss.getJSONObject(i);quotes.put(r.getString("id"),r.opt("quote"));}
  JSONObject current=sources(CandidateThemeSelection.strings(raw.getJSONObject("accountScope").getJSONArray("accountIds")),quotes,c);for(String key:new String[]{"holdings","recent","leaders"}){JSONObject packet=raw.getJSONObject("sources").getJSONObject(key),expected=new JSONObject(packet.getJSONObject("readEvidence").toString()).put("data",packet.get("data"));need(LocalCandidateModel.canonical(expected).equals(LocalCandidateModel.canonical(current.get(key))),"预览后背景来源已变化；旧证据保留，请重新预览");}active(c);
 }
 JSONObject completePreview(JSONObject p,BooleanSupplier c)throws Exception{need(p.optString("schema").equals("native-candidate-background-preview/v1")&&p.length()==4,"完整背景预览无效");JSONObject adapter=p.getJSONObject("adapter");LocalCandidateBackgroundAdapter.verify(adapter);JSONObject raw=adapter.getJSONObject("input");confirmLive(raw,c);JSONObject result=LocalCandidateModel.evaluate(LocalCandidateModel.snapshot(p.getJSONArray("inputs"),p.getString("strategy"),Instant.parse(raw.getString("capturedAt"))));JSONObject bundle=new JSONObject().put("schema",SCHEMA).put("adapter",adapter).put("result",result);verify(bundle,c);confirmLive(raw,c);return bundle;}
 JSONObject capture(JSONArray s,String t,List<String>a,BooleanSupplier c)throws Exception{return completePreview(prepare(s,t,a,null,c),c);}
 static void verify(JSONObject bundle,BooleanSupplier c)throws Exception{active(c);need(SCHEMA.equals(bundle.optString("schema"))&&bundle.length()==3,"背景留存格式不支持");JSONObject adapter=bundle.getJSONObject("adapter"),result=bundle.getJSONObject("result");LocalCandidateBackgroundAdapter.verify(adapter);LocalCandidateModel.verify(result);JSONObject input=result.getJSONObject("input"),raw=adapter.getJSONObject("input"),backgrounds=adapter.getJSONObject("backgrounds");need(Instant.parse(input.getString("capturedAt")).equals(Instant.parse(raw.getString("capturedAt")))&&("native-candidate-background-sources/v2-business-demand".equals(raw.optString("schema"))?LocalCandidateBackground.BUSINESS_CANDIDATE_VERSION:LocalCandidateBackground.CANDIDATE_VERSION).equals(input.optString("model")),"背景与技术结果的版本/观察时刻不同");Set<String>ids=new HashSet<>();JSONArray rows=input.getJSONArray("inputs");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String id=row.getString("id");need(ids.add(id)&&backgrounds.has(id)&&LocalCandidateBackgroundAdapter.canonical(row.get("backgroundInput")).equals(LocalCandidateBackgroundAdapter.canonical(backgrounds.get(id))),"完整adapter与结果未绑定同一背景");}need(ids.size()==backgrounds.length(),"背景证券范围不一致");if(raw.has("themeSelection")){JSONObject held=raw.getJSONObject("themeSelection");CandidateThemeSelection.verify(held,c);JSONArray plain=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=new JSONObject(rows.getJSONObject(i).toString());row.remove("backgroundInput");plain.put(row);}need(LocalCandidateModel.canonical(LocalCandidateModel.snapshot(held.getJSONArray("securities"),input.getString("strategy"),Instant.parse(input.getString("capturedAt"))).getJSONArray("inputs")).equals(LocalCandidateModel.canonical(plain)),"证券版本与主题证据不一致");for(String key:new String[]{"themes","demand"})need(LocalCandidateModel.canonical(raw.getJSONObject("sources").getJSONObject(key).get("data")).equals(LocalCandidateModel.canonical(held.get(key))),"主题选择与模型输入不一致");CandidateThemeSelection.clocks(held,Instant.parse(raw.getString("capturedAt")));}}
 static long scalar(SQLiteDatabase db,String query)throws Exception{try(Cursor q=db.rawQuery(query,null)){need(q.moveToFirst(),"背景库查询失败");return q.getLong(0);}}
 static final android.database.DatabaseErrorHandler KEEP_CORRUPT_FILE=corrupt->{throw new SQLiteDatabaseCorruptException("背景证据损坏；拒绝自动删除或修复");};
 static boolean sqliteHeader(File file)throws IOException{try(InputStream in=new FileInputStream(file)){byte[] head=new byte[16];int offset=0,n;while(offset<16&&(n=in.read(head,offset,16-offset))>0)offset+=n;return offset==16&&Arrays.equals(head,"SQLite format 3\000".getBytes(StandardCharsets.US_ASCII));}}
 static void verifyIdentity(SQLiteDatabase db)throws Exception{need(scalar(db,"PRAGMA application_id")==APP,"不是本机背景专用库，未以写连接打开");need(db.getVersion()<=1,"背景证据库版本过高");}
 SQLiteDatabase open(boolean write,BooleanSupplier c)throws Exception{
  active(c);if(write)protectSources();need(evidence.getAbsoluteFile().getParentFile().isDirectory(),"背景留存目录不存在");boolean fresh=false;
  if(!evidence.exists()){need(write,"背景证据不存在");need(evidence.createNewFile(),"背景路径出现并发文件，未采用");fresh=true;}
  if(!fresh){need(sqliteHeader(evidence),"背景库文件头无效；原文件保留");try(SQLiteDatabase guard=SQLiteDatabase.openDatabase(evidence.getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY|SQLiteDatabase.NO_LOCALIZED_COLLATORS,KEEP_CORRUPT_FILE)){verifyIdentity(guard);}}
  SQLiteDatabase db=SQLiteDatabase.openDatabase(evidence.getAbsolutePath(),null,SQLiteDatabase.NO_LOCALIZED_COLLATORS|(write?SQLiteDatabase.OPEN_READWRITE:SQLiteDatabase.OPEN_READONLY),KEEP_CORRUPT_FILE);try{
   try(Cursor q=db.rawQuery("PRAGMA busy_timeout=100",null)){q.moveToFirst();}long app=scalar(db,"PRAGMA application_id");need(fresh?app==0&&scalar(db,"SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name<>'android_metadata'")==0:app==APP,"不是本机背景专用库，未写入");need(db.getVersion()<=1,"背景证据库版本过高");
   if(write){db.execSQL("PRAGMA synchronous=FULL");db.beginTransaction();try{db.execSQL("CREATE TABLE IF NOT EXISTS bundles(digest TEXT PRIMARY KEY,payload TEXT NOT NULL)");db.execSQL("CREATE TABLE IF NOT EXISTS draft(id INTEGER PRIMARY KEY CHECK(id=1),digest TEXT NOT NULL)");db.execSQL("CREATE TABLE IF NOT EXISTS history(id TEXT PRIMARY KEY,title TEXT NOT NULL,saved_at TEXT NOT NULL,digest TEXT NOT NULL)");db.execSQL("PRAGMA application_id="+APP);db.setVersion(1);active(c);db.setTransactionSuccessful();}finally{db.endTransaction();}}return db;
  }catch(Exception e){db.close();throw e;}
 }
 static void requireReadTransaction(){if(android.os.Build.VERSION.SDK_INT<35)throw new UnsupportedOperationException("当前Android不支持正式只读事务；背景完整读取不可用，未降级为写事务");}
 static void readTransaction(SQLiteDatabase db){requireReadTransaction();db.beginTransactionReadOnly();}
 static String storedHead(SQLiteDatabase db){try(Cursor q=db.rawQuery("SELECT digest FROM draft WHERE id=1",null)){return q.moveToFirst()?q.getString(0):"";}}
 static JSONObject bundle(SQLiteDatabase db,String digest,BooleanSupplier c)throws Exception{long length;try(Cursor q=db.rawQuery("SELECT length(CAST(payload AS BLOB)) FROM bundles WHERE digest=?",new String[]{digest})){need(q.moveToFirst(),"冻结背景证据不存在或已被替换");length=q.getLong(0);}need(length>0&&length<=LIMIT,"背景证据超限");ByteArrayOutputStream out=new ByteArrayOutputStream();for(long offset=0;offset<length;offset+=65536){active(c);try(Cursor part=db.rawQuery("SELECT substr(CAST(payload AS BLOB),?,65536) FROM bundles WHERE digest=?",new String[]{Long.toString(offset+1),digest})){need(part.moveToFirst(),"背景证据缺块");byte[] bytes=part.getBlob(0);need(bytes.length==Math.min(65536,length-offset),"背景证据不完整");out.write(bytes);}}byte[] bytes=out.toByteArray();String text=new String(bytes,StandardCharsets.UTF_8);need(Arrays.equals(bytes,text.getBytes(StandardCharsets.UTF_8)),"背景证据UTF8损坏");JSONObject value=new JSONObject(text);verify(value,c);need(digest(value).equals(digest),"背景证据摘要不符");return value;}
 static String insert(SQLiteDatabase db,JSONObject value,BooleanSupplier c)throws Exception{verify(value,c);String text=value.toString(),digest=digest(value);need(text.getBytes(StandardCharsets.UTF_8).length<=LIMIT,"完整背景证据超过12MiB，未截断");ContentValues row=new ContentValues();row.put("digest",digest);row.put("payload",text);db.insertWithOnConflict("bundles",null,row,SQLiteDatabase.CONFLICT_IGNORE);need(LocalCandidateBackgroundAdapter.canonical(bundle(db,digest,c)).equals(LocalCandidateBackgroundAdapter.canonical(value)),"背景写后读回不符");return digest;}
 static void prune(SQLiteDatabase db){db.execSQL("DELETE FROM bundles WHERE digest NOT IN (SELECT digest FROM draft UNION SELECT digest FROM history)");}
 String head(BooleanSupplier c)throws Exception{active(c);if(!evidence.exists())return "";try(SQLiteDatabase db=open(false,c)){return storedHead(db);}}
 String putDraft(JSONObject value,String expected,BooleanSupplier c)throws Exception{verify(value,c);JSONObject raw=value.getJSONObject("adapter").getJSONObject("input");confirmLive(raw,c);try(SQLiteDatabase db=open(true,c)){db.beginTransaction();try{need(storedHead(db).equals(expected),"背景草稿已变化，未覆盖较新结果");String digest=insert(db,value,c);ContentValues row=new ContentValues();row.put("id",1);row.put("digest",digest);need(db.insertWithOnConflict("draft",null,row,SQLiteDatabase.CONFLICT_REPLACE)!=-1,"背景草稿保存失败");prune(db);if(hooks!=null)hooks.beforeCommit();confirmLive(raw,c);active(c);db.setTransactionSuccessful();return digest;}finally{db.endTransaction();}}}
 JSONObject readDraft(String anchor,BooleanSupplier c)throws Exception{requireReadTransaction();try(SQLiteDatabase db=open(false,c)){readTransaction(db);try{need(!anchor.isEmpty()&&anchor.equals(storedHead(db)),"背景草稿已失效，不会读取较新的计算");return bundle(db,anchor,c);}finally{db.endTransaction();}}}
 String save(String title,JSONObject value,Instant now,BooleanSupplier c)throws Exception{title=title==null?"":title.trim();need(!title.isEmpty()&&title.length()<=120&&now!=null,"请输入1至120字名称");verify(value,c);JSONObject raw=value.getJSONObject("adapter").getJSONObject("input");confirmLive(raw,c);try(SQLiteDatabase db=open(true,c)){db.beginTransaction();try{if(raw.has("themeSelection"))need(storedHead(db).equals(digest(value)),"背景草稿版本已变化，未另存过期预览");need(scalar(db,"SELECT count(*) FROM history")<100,"背景历史已达100份，请明确删除");String digest=insert(db,value,c),id=UUID.randomUUID().toString();ContentValues row=new ContentValues();row.put("id",id);row.put("title",title);row.put("saved_at",now.toString());row.put("digest",digest);need(db.insertOrThrow("history",null,row)!=-1,"背景历史保存失败");if(hooks!=null)hooks.beforeCommit();confirmLive(raw,c);active(c);db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}}
 JSONArray list(BooleanSupplier c)throws Exception{active(c);JSONArray out=new JSONArray();if(!evidence.exists())return out;try(SQLiteDatabase db=open(false,c);Cursor q=db.rawQuery("SELECT id,title,saved_at,digest FROM history ORDER BY saved_at DESC,id LIMIT 101",null)){while(q.moveToNext()){active(c);need(out.length()<100,"背景历史超限");out.put(new JSONObject().put("id",q.getString(0)).put("title",q.getString(1)).put("savedAt",q.getString(2)).put("digest",q.getString(3)));}}return out;}
 JSONObject read(String id,BooleanSupplier c)throws Exception{requireReadTransaction();try(SQLiteDatabase db=open(false,c)){readTransaction(db);try(Cursor q=db.rawQuery("SELECT title,saved_at,digest FROM history WHERE id=?",new String[]{id})){need(q.moveToFirst(),"背景历史不存在");return new JSONObject().put("id",id).put("title",q.getString(0)).put("savedAt",q.getString(1)).put("digest",q.getString(2)).put("bundle",bundle(db,q.getString(2),c));}finally{db.endTransaction();}}}
 void remove(String id,String expected,BooleanSupplier c)throws Exception{try(SQLiteDatabase db=open(true,c)){db.beginTransaction();try{need(db.delete("history","id=? AND digest=?",new String[]{id,expected})==1,"背景历史已变化或删除");prune(db);active(c);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
}
